import type { SyncRefinedResult } from '@resultsafe/core-fp-result';
type M={a:{payload:'id'}}; type V={id:(x:unknown)=>x is string}; type X=SyncRefinedResult<'a',M,V>; const x:X={type:'a',id:'x'};
const bad: SyncRefinedResult<never,never,never>={type:'bad'};

import type { SyncRefinedResultUnion } from '@resultsafe/core-fp-result';
type M={a:{payload:'id'},b:{payload:'never'}}; type V={a:{id:(x:unknown)=>x is string},b:{}}; type X=SyncRefinedResultUnion<M,V>; const a:X={type:'a',id:'x'}; const b:X={type:'b'};
const bad: SyncRefinedResultUnion<never,never,never>={type:'bad'};

import type { SyncValidatorMap } from '@resultsafe/core-fp-result';
type M={a:{payload:'id'}}; const v:SyncValidatorMap<M>={a:{id:(x:unknown):x is string=>typeof x==='string'}};
const bad: SyncValidatorMap<never,never,never>={type:'bad'};

import type { UniversalAsyncRefinedResult } from '@resultsafe/core-fp-result';
type M={a:{payload:'id'}}; type V={id:(x:unknown)=>Promise<boolean>}; const x:UniversalAsyncRefinedResult<'a',M,V>={type:'a',id:'x'};
const bad: UniversalAsyncRefinedResult<never,never,never>={type:'bad'};

import type { UniversalRefinedResult } from '@resultsafe/core-fp-result';
type M={a:{payload:'id'}}; type V={id:(x:unknown)=>x is string}; const x:UniversalRefinedResult<'a',M,V>={type:'a',id:'x'};
const bad: UniversalRefinedResult<never,never,never>={type:'bad'};

import type { VariantOf } from '@resultsafe/core-fp-result';
type X=VariantOf<'a'|'b'>; const a:X={type:'a'}; const b:X={type:'b'};
const bad: VariantOf<never,never,never>={type:'bad'};
